_PINF = float("inf")
_INT32_LIMIT = 2**31 - 1
_SPC_TARGET = 48
_TILE_BYTES = 8192


@triton.jit
def _renorm_term(x, P_MODE: tl.constexpr, p):
    """Contribution of one element to the p-norm sum."""
    if P_MODE == 1:
        return tl.abs(x)
    if P_MODE == 2:
        return x * x
    if P_MODE == 3:
        return x * x * tl.abs(x)
    if P_MODE == 4:
        return tl.abs(x)
    return libdevice.pow(tl.abs(x), p)


@triton.jit
def _renorm_norm(acc, P_MODE: tl.constexpr, inv_p):
    """Slice norm from the finished accumulation."""
    if P_MODE == 1:
        return acc
    if P_MODE == 2:
        return tl.sqrt(acc)
    if P_MODE == 4:
        return acc
    return libdevice.pow(acc, inv_p)


